extern alias wire;
using W=wire::Offline3D;
using Offline3D;
using System.Text.Json;
int passed=0;
void Check(string name,Action f){f();passed++;Console.WriteLine("PASS "+name);}
void Equal(bool b){if(!b)throw new Exception("Comparison failed");}
void Reject(Action f){try{f();}catch(InvalidDataException){return;}throw new Exception("Expected invalid output rejection");}
bool Same(JsonElement a,JsonElement b){if(a.ValueKind!=b.ValueKind)return false;switch(a.ValueKind){case JsonValueKind.Object:var x=a.EnumerateObject().ToDictionary(p=>p.Name,p=>p.Value);var y=b.EnumerateObject().ToDictionary(p=>p.Name,p=>p.Value);return x.Count==y.Count&&x.All(p=>y.ContainsKey(p.Key)&&Same(p.Value,y[p.Key]));case JsonValueKind.Array:return a.GetArrayLength()==b.GetArrayLength()&&a.EnumerateArray().Zip(b.EnumerateArray(),(v,w)=>Same(v,w)).All(v=>v);case JsonValueKind.Number:return a.GetDouble()==b.GetDouble();case JsonValueKind.String:return a.GetString()==b.GetString();default:return a.GetRawText()==b.GetRawText();}}
void Compare(byte[] a,byte[] b){using var x=JsonDocument.Parse(a);using var y=JsonDocument.Parse(b);Equal(Same(x.RootElement,y.RootElement));}
var draft=new W.Registration{DocumentId="doc-שלום",ViewId="plan-\"A\"",LevelId="L2",LevelProjectElevationFeet=12.25,ModelToGraphics=W.Matrix4.Graphics(new W.Point3(1e6,-2e6,12.25)),CropSheet=new[]{-2d,0,2,0,2,3,-2,3}};
Check("registration draft roundtrips through unchanged viewer decoder",()=>{var bytes=W.Contract.Encode(draft);var decoded=Contract.Decode<Registration>(bytes);Equal(decoded.DocumentId==draft.DocumentId&&decoded.ViewId==draft.ViewId&&decoded.ModelToGraphics.Values.SequenceEqual(draft.ModelToGraphics.Values));Compare(bytes,Contract.Encode(decoded));});
Check("25 automatic sheet markers match viewer schema",()=>{var bytes=W.Contract.Encode(W.AutomaticExport.Markers(draft.CropSheet));var decoded=Contract.Decode<SheetMarker[]>(bytes);Equal(decoded.Length==25&&decoded.Select(x=>x.Id).SequenceEqual(Enumerable.Range(0,25)));Compare(bytes,Contract.Encode(AutomaticExport.Markers(draft.CropSheet)));});
Check("identities preserve unicode quotes nulls and mesh names",()=>{var ids=new[]{new W.ElementIdentity{UniqueId="element\\one\n\"😀שלום",DocumentId="host",MeshName="m/0",Category="Walls",TypeName="Concrete 200mm",MaterialName="Concrete",CutPatternName="Concrete fill"}};var bytes=W.Contract.Encode(ids);var decoded=Contract.Decode<ElementIdentity[]>(bytes);Equal(decoded[0].UniqueId==ids[0].UniqueId&&decoded[0].LinkInstanceId==null&&decoded[0].TypeName=="Concrete 200mm"&&decoded[0].CutPatternName=="Concrete fill");Compare(bytes,Contract.Encode(decoded));});
Check("control candidate anonymous values preserve exact numeric coordinates",()=>{var values=new object[]{new{source="crop-corner",modelX=-1.23456789012345e6,modelY=1e-200,sheetX=12.3,sheetY=45d}};Compare(W.Contract.Encode(values),Contract.Encode(values));});
Check("escaped JSON strings and controls roundtrip",()=>{var chars=new[]{"\"\\\b\f\n\r\t\0\u001f","אבג 😀 \u2028 \u2029","<script>&/"};Equal(JsonSerializer.Deserialize<string[]>(W.Contract.Encode(chars))!.SequenceEqual(chars));});
Check("numbers roundtrip invariantly under a comma-decimal culture",()=>{var old=System.Globalization.CultureInfo.CurrentCulture;try{System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("fr-FR");var values=new[]{double.Epsilon,double.MaxValue,-0d,-1.2345678901234567,1e-100};Equal(JsonSerializer.Deserialize<double[]>(W.Contract.Encode(values))!.SequenceEqual(values));}finally{System.Globalization.CultureInfo.CurrentCulture=old;}});
Check("camel-case DTOs and exact uppercase glTF keys differ correctly",()=>{var obj=new{POSITION=2,NORMAL=3};using var dto=JsonDocument.Parse(W.Contract.Encode(obj));using var gltf=JsonDocument.Parse(W.Contract.EncodeExact(obj));Equal(dto.RootElement.GetProperty("position").GetInt32()==2&&gltf.RootElement.GetProperty("POSITION").GetInt32()==2);});
Check("NaN is rejected",()=>Reject(()=>W.Contract.Encode(new{v=double.NaN})));
Check("infinity is rejected",()=>Reject(()=>W.Contract.Encode(new[]{double.PositiveInfinity})));
var mesh=W.GlbBuilder.Box("wall-שלום",new W.Point3(),new W.Point3(10,2,12));mesh.Material=new W.PlainMaterial{Name="Blue",Red=.1,Green=.3,Blue=.8,Roughness=.2,Metallic=.7,Opacity=.8};
mesh.Material.CutPattern=new W.CutPatternDefinition{Name="Concrete",Target="Drafting",Grids=new[]{new W.CutGridDefinition{Angle=.5,OffsetFeet=.05,ShiftFeet=.1,SegmentsFeet=new[]{.02,-.01}}}};
byte[] glb=W.GlbBuilder.Encode(new[]{mesh},W.Matrix4.Graphics(new W.Point3()));
Check("wire GLB passes unchanged strict viewer validation",()=>Contract.ValidateGlb(glb));
Check("GLB preserves POSITION NORMAL indices and PBR material",()=>{int n=BitConverter.ToInt32(glb,12);using var d=JsonDocument.Parse(glb.AsMemory(20,n));var root=d.RootElement;Equal(root.GetProperty("materials")[0].GetProperty("extras").GetProperty("cutPattern").GetProperty("Name").GetString()=="Concrete");Equal(root.GetProperty("meshes")[0].GetProperty("primitives")[0].GetProperty("attributes").GetProperty("NORMAL").GetInt32()==1);Equal(Math.Abs(root.GetProperty("materials")[0].GetProperty("pbrMetallicRoughness").GetProperty("metallicFactor").GetDouble()-.7)<1e-12);});
Check("material hashing is stable and respects changes",()=>{var a=W.Contract.Hash(W.Contract.Encode(mesh.Material));Equal(a==W.Contract.Hash(W.Contract.Encode(mesh.Material)));mesh.Material.Red=.2;Equal(a!=W.Contract.Hash(W.Contract.Encode(mesh.Material)));});
Check("registration JSON can be embedded and read by unchanged PDF packager",()=>{var reg=Contract.Decode<Registration>(W.Contract.Encode(draft));reg.ModelToPdf=Matrix4.Identity;reg.PreciseClicks=true;reg.MediaBox=reg.PageCropBox=new[]{0d,0,612,792};reg.CropPdf=new[]{0d,0,100,0,100,100,0,100};reg.FitPointCount=reg.CheckPointCount=3;Contract.Validate(reg);Equal(Contract.Decode<Registration>(Contract.Encode(reg)).ViewId==draft.ViewId);});
Console.WriteLine(passed+" exporter/viewer wire interoperability checks passed; Linux .NET 8, not Revit runtime.");
